style.css:
@-moz-document domain("pinterest.com") {
/* --- GLOBAL BACKGROUND & TEXT --- */
    body, 
    #HeaderContent, 
    .Header,
    [data-test-id="header"] {
        background-color: #FEFAF9 !important; /* Vista White */
        color: #CBC5C5 !important;           /* Pale Slate */
    }

    /* --- HOMEFEED & PINS CONTAINER --- */
    [data-test-id="grid"] {
        background-color: #FEFAF9 !important;
    }

    /* --- PIN CARDS --- */
    [data-test-id="pin"] img {
        border-radius: 16px !important;
        transition: transform 0.3s ease, box-shadow 0.3s ease !important;
    }
    
    [data-test-id="pin"]:hover img {
        transform: translateY(-4px);
        box-shadow: 0 8px 24px rgba(203, 197, 197, 0.4) !important; /* Soft Pale Slate Shadow */
    }

    /* --- SEARCH BAR --- */
    [data-test-id="search-box-input"],
    [data-test-id="search-box"] form {
        background-color: #F2ECEC !important; /* Soft Peach */
        border: 1px solid #DBD5D5 !important;  /* Swiss Coffee */
        border-radius: 24px !important;
        color: #CBC5C5 !important;
    }

    /* --- BUTTONS & MODALS --- */
    /* Primary buttons (like Save) */
    [data-test-id="NotificationBellButton"],
    [data-test-id="HeaderChatButton"],
    .red-button, 
    [style*="background-color: rgb(230, 0, 35)"] {
        background-color: #FEF4F5 !important; /* Chablis */
        color: #CBC5C5 !important;
        border: 1px solid #F2ECEC !important;
    }

    [data-test-id="NotificationBellButton"]:hover,
    .red-button:hover {
        background-color: #F2ECEC !important; /* Soft Peach hover */
    }

    /* Secondary/Standard Buttons */
    button, [role="button"] {
        border-radius: 20px !important;
    }
}
